use std::cell::RefCell;
fn main() {
    let value = RefCell::new(7);
    let reader = value.borrow();
    assert!(value.try_borrow_mut().is_err());
    assert_eq!(*reader, 7);
    drop(reader);
    *value.borrow_mut() = 9;
    assert_eq!(*value.borrow(), 9);
}

